-- Shared Content Studio submissions and atomic administrator approval to Beta.
-- Run after 202609270001_workspace_members.sql as the project administrator.
begin;
alter table public.workspace_members add column if not exists role text not null default 'member'
  check (role in ('member','admin'));

create or replace function public.workspace_role() returns text
language sql stable security definer set search_path = '' as $$
  select role from public.workspace_members where user_id = auth.uid() and active;
$$;
revoke all on function public.workspace_role() from public, anon;
grant execute on function public.workspace_role() to authenticated;

create table public.workspace_content_sources (
 course text not null check (course in ('aws1','ped')),
 chapter text not null check (chapter in ('c2','c3')),
 slots jsonb not null, primary key(course,chapter)
);
insert into public.workspace_content_sources(course,chapter,slots) values
('aws1','c2','{"c2.examples": [{"title": "Connecting studies in a literature review", "thinking": "I need to find a way to connect these two studies for my literature review. One is about social media and self esteem, the other is about screen time and sleep. My professor said the transition between paragraphs matters a lot. I tried linking them through \"adolescent wellbeing\" but it felt too vague. I want something more specific but I am not sure what that would look like.", "typing_note": "[uploads two PDFs]", "typing": "\"How do I connect these two studies in my literature review?\"", "processing": "Full text of both papers is processed. Themes, findings, methodologies, theoretical frameworks all extracted. The most statistically likely \"helpful\" response pattern for \"connect these two studies\" is activated. → Generate a comprehensive answer covering multiple possible connection points: shared constructs, overlapping populations, complementary findings, theoretical alignment. Present them as options. Sound confident and thorough."}, {"title": "Creating practice questions", "thinking": "My exam is next week and I want to test myself on chapter 4. The professor always writes tricky MCQs where two options look almost the same and you have to know the exact definition to tell them apart. I need questions that are at that level, not the easy ones where you can guess by elimination.", "typing_note": "[pastes chapter 4 text]", "typing": "\"Make me some MCQs on chapter 4.\"", "processing": "Full chapter text is processed. Key concepts, definitions, and relationships identified. \"MCQ\" triggers a default format: one correct answer, three distractors, medium difficulty, recall focused. → Generate questions that cover the chapter evenly, make distractors plausible but clearly distinguishable from the correct answer."}, {"title": "Summarizing a paper", "thinking": "I read this paper but I am not sure I understood the method section. I think they used a between subjects design but the way they describe the groups is confusing. I do not need a full summary, I just need someone to explain the design so I can figure out whether their conclusion actually follows from it.", "typing_note": "[uploads PDF]", "typing": "\"Can you summarize this paper?\"", "processing": "Full paper is processed. All sections weighted. \"Summarize\" triggers a default structure: background, aim, method, key findings, conclusion. Roughly equal coverage across sections. → Produce something that reads like a complete, balanced overview. Sound clear and organized."}, {"title": "Understanding a concept", "thinking": "The professor used the term \"ecological validity\" in the lecture today and I kind of got it from context, but when I tried to explain it to my friend I couldn''t. I think it has something to do with how realistic a study is, but I am not sure if it is about the setting, the task, or both. And I am confused about how it is different from external validity because they sound like they overlap.", "typing": "\"What is ecological validity?\"", "processing": "A definition request. \"Ecological validity\" is a well represented concept in the training data. → Generate a clear, textbook style definition. Add an example. Possibly mention related terms. Present a self contained explanation, covering the concept broadly rather than targeting any specific point of confusion."}, {"title": "Asking for feedback on your writing", "thinking": "I spent two hours on this introduction and I think the argument flows okay, but the last sentence feels weak. My tutor told me last time that I tend to state things too broadly without committing to a clear position. I want to know if I am doing that again here, specifically in the last two sentences.", "typing_note": "[pastes paragraph]", "typing": "\"What do you think of this? Any feedback?\"", "processing": "A paragraph is provided. Feedback requested with no specific focus. → Scan for grammar, clarity, structure, and argument strength across the entire paragraph. Generate a balanced set of comments covering multiple aspects. Highlight positives first, then suggest improvements. Distribute attention evenly across the whole text."}, {"title": "Writing a motivation letter", "thinking": "I am applying for this internship at a research lab and I really want it because the supervisor published a paper I referenced in my thesis. I have some relevant experience from my stats course and a small project I did with a classmate, but I am not sure if that counts. The deadline is tomorrow and I saw that they value \"independent thinkers\" but I do not want to sound arrogant.", "typing": "\"Help me write a motivation letter for a research internship.\"", "processing": "A motivation letter for a research internship. No specific lab, no field, no applicant background, no deadline pressure, no tone preference. → Generate a polished, general purpose motivation letter template. Use broadly applicable language about \"passion for research\" and \"eagerness to learn.\" Structure it in a standard format. Sound professional and enthusiastic."}]}'::jsonb),
('aws1','c3','{"c3.techniques.clear_instruction": {"bad": "\"Summarize this paper\"", "good": "\"Summarize this paper''s main argument and research methodology in two sentences each. This is for an undergraduate psychology class presentation.\""}, "c3.techniques.role": {"bad": "\"Check my Boolean search string\"", "good": "\"You are a search strategy advisor for academic databases. Review the Boolean search string I wrote. If there are logical errors, don''t fix them directly — ask me questions about what went wrong.\""}, "c3.techniques.task_decomposition": {"bad": "\"Build my literature review outline\"", "good": "Step 1: \"Extract the common themes from the five papers I read\" → Step 2: \"Map the relationships between those themes\" → Step 3: \"Suggest possible outline structures based on those relationships\""}, "c3.techniques.few_shot": {"good": "\"Summarize each paper''s core claim in one sentence, like this:\nSmith (2022): Social media use is positively associated with anxiety in adolescents, mediated by sleep disruption.\nDo the same for the remaining three papers.\""}, "c3.techniques.chain_of_thought": {"bad": "\"Are the conclusions of these two papers contradictory?\"", "good": "\"Determine whether the conclusions of these two papers contradict each other. First, summarize each paper''s core claim. Then compare where they overlap and where they differ. Finally, explain step by step whether the difference is a genuine contradiction or a difference in scope or conditions.\""}, "c3.techniques.output_format": {"bad": "\"Compare these three papers\"", "good": "\"Create a comparison table for these three papers. Columns: author/year, research question, methodology, key findings, limitations. One sentence per cell.\""}, "c3.critique.read": "Student asked \"Extract the common themes from these three papers.\" AI returned three paragraphs. Observation: AI identified three themes, assigned papers to each, and wrote in paragraph form.", "c3.critique.question": "Are these three themes actually from the papers, or did AI generalize? Is the third theme too broad? Paper B is assigned to two themes — is that accurate? I only asked for common themes, but AI added \"implications\" — did it exceed my request scope?", "c3.critique.verify": "Checking Paper A: AI''s first theme is correct but was a secondary point, not the core finding. The third theme uses phrasing that doesn''t appear in any original paper — AI generalized. The \"implications\" section covers a stage I haven''t reached yet.", "c3.critique.decide": "Themes 1 and 2 are usable as starting points. Theme 3 is discarded. The implications section is deleted. Theme 2''s paper assignment needs verification — may re-prompt after checking the original.", "c3.amd_example": {"title": "Worked example — Common theme extraction", "intro": "Student asked AI to extract common themes from three papers. AI presented three themes:", "items": [{"text": "Theme 1: \"Sleep disruption as a mediator between screen time and adolescent anxiety\"", "tag": "adopt", "reason": "Matches the original papers. Usable as an outline starting point. Placed as starting point for first outline section."}, {"text": "Theme 2: \"The role of parental monitoring in mitigating digital harm\"", "tag": "modify", "reason": "Direction is correct but AI generalized \"social media exposure\" into \"digital harm.\" Corrected to \"social media exposure.\" Original paper re-checked."}, {"text": "Theme 3: \"Broader implications for public health policy\"", "tag": "discard", "reason": "I asked for common themes, not implications. This topic does not appear in the papers. AI fabricated it. Deleted. Record: \"AI exceeded request scope by adding implications.\""}]}, "c3.template_compare.md": [{"heading": "Role", "lines": ["You are a literature analysis assistant."]}, {"heading": "Task", "lines": ["Identify common themes across three papers."]}, {"heading": "Context", "lines": ["I am writing a literature review for AWS."]}, {"heading": "Constraints", "lines": ["- Do not summarize each paper individually", "- Stay at theme identification only"]}, {"heading": "Output Format", "lines": ["Numbered list, one sentence per theme."]}], "c3.template_compare.xml": [{"tag": "role", "lines": ["You are a literature analysis assistant."]}, {"tag": "task", "lines": ["Identify common themes across three papers."]}, {"tag": "context", "lines": ["I am writing a literature review for AWS."]}, {"tag": "constraints", "lines": ["Do not summarize each paper individually.", "Stay at theme identification only."]}, {"tag": "output_format", "lines": ["Numbered list, one sentence per theme."]}], "c3.full_example_title": "Full worked example — Common theme extraction from three papers", "c3.full_example": [{"tag": "role", "lines": ["You are an academic literature analysis assistant", "for a first-year psychology student."]}, {"tag": "task", "lines": ["Identify the common themes across the following", "three journal articles. Focus on overlapping", "research topics, not methodological similarities."]}, {"tag": "context", "lines": ["I am writing a literature review for my Academic", "Writing Skills course. I have read all three papers.", "I am currently at the stage of organizing my sources", "before drafting an outline."]}, {"tag": "constraints", "lines": ["Do not summarize each paper individually.", "Do not suggest an outline or structure.", "Stay at the level of theme identification only."]}, {"tag": "steps", "lines": ["1. Read the three abstracts I provide below.", "2. Identify recurring topics or constructs.", "3. Group them into distinct themes."]}, {"tag": "examples", "lines": ["Example theme format:", "\"Sleep disruption as a mediator between screen time", "and adolescent anxiety (Paper A, Paper C)\""]}, {"tag": "output_format", "lines": ["A numbered list of 3–5 common themes.", "Each theme in one sentence, with the relevant", "paper(s) noted in parentheses."]}]}'::jsonb),
('ped','c2','{"c2.examples": [{"title": "Connecting an article to an argument in a scientific essay", "thinking": "I want to use this article in my scientific essay because I think it supports my statement, but I''m not sure how to make the connection. My statement is that schools should play a larger role in preventing child maltreatment. Based on its findings, I think that the article could support an argument about the importance of early identification and support in schools, but I am not sure how to translate this idea into a strong argument.", "typing_note": "[uploads a PDF]", "typing": "\"How can I use this article to support my statement in my scientific essay?\"", "processing": "The full text of the article is processed. Main findings, theoretical concepts, and conclusions are extracted. The most statistically likely \"helpful\" response pattern for \"how can I use this article to support my statement\" is activated. → Generate a comprehensive answer covering multiple possible ways to translate the article into an argument: relevant findings, connections between evidence and the statement, theoretical explanations, and possible ways to integrate the article into the essay. Present them as options. Sound confident and thorough."}, {"title": "Creating practice questions", "thinking": "My exam is next week and I want to test myself on chapter 4. The professor always writes tricky MCQs where two options look almost the same and you have to know the exact definition to tell them apart. I need questions that are at that level, not the easy ones where you can guess by elimination.", "typing_note": "[pastes chapter 4 text]", "typing": "\"Make me some MCQs on chapter 4.\"", "processing": "Full chapter text is processed. Key concepts, definitions, and relationships identified. \"MCQ\" triggers a default format: one correct answer, three distractors, medium difficulty, recall focused. → Generate questions that cover the chapter evenly, make distractors plausible but clearly distinguishable from the correct answer."}, {"title": "Summarizing a paper", "thinking": "I read this paper but I am not sure I understood the method section. I think they used a between subjects design but the way they describe the groups is confusing. I do not need a full summary, I just need someone to explain the design so I can figure out whether their conclusion actually follows from it.", "typing_note": "[uploads PDF]", "typing": "\"Can you summarize this paper?\"", "processing": "Full paper is processed. All sections weighted. \"Summarize\" triggers a default structure: background, aim, method, key findings, conclusion. Roughly equal coverage across sections. → Produce something that reads like a complete, balanced overview. Sound clear and organized."}, {"title": "Understanding a concept", "thinking": "The professor used the term \"protective factors\" in the lecture today and I kind of got it from context, but when I tried to explain it to my friend I couldn''t. I think it has something to do with factors that help children develop positively, but I am not sure how it differs from simply having a good environment or fewer risk factors.", "typing_note": "", "typing": "\"What are protective factors?\"", "processing": "A definition request. \"Protective factors\" is a well represented concept in the training data. → Generate a clear, textbook style definition. Add an example. Possibly mention related terms. Present a self contained explanation, covering the concept broadly rather than targeting any specific point of confusion."}, {"title": "Asking for feedback on your writing", "thinking": "I spent two hours on this introduction and I think I explain the pedagogical dilemma clearly, but I am not sure whether the last two sentences lead naturally to my statement. My tutor told me last time that I tend to overcomplicate my sentences and explanations, and I want to know if I am doing that again here.", "typing_note": "[pastes paragraph]", "typing": "\"What do you think of this? Any feedback?\"", "processing": "A paragraph is provided. Feedback requested with no specific focus. → Scan for grammar, clarity, structure, and argument strength across the entire paragraph. Generate a balanced set of comments covering multiple aspects. Highlight positives first, then suggest improvements. Distribute attention evenly across the whole text."}, {"title": "Writing a motivation letter", "thinking": "I am applying for an internship at a youth care organization, and I really want it because I would like to gain practical experience working with children and families. I have some relevant experience from my courses and volunteer work, but I am not sure whether it is enough to mention in my motivation letter. The deadline is tomorrow and I saw that they value \"independent thinkers\" but I do not want to sound arrogant.", "typing_note": "", "typing": "\"Help me write a motivation letter for a youth care internship.\"", "processing": "A motivation letter for a youth care internship. No specific organization, no specific tasks, no applicant background, no deadline pressure, no tone preference. → Generate a polished, general purpose motivation letter template. Use broadly applicable language about \"passion for children and youth\" and \"eagerness to learn.\" Structure it in a standard format. Sound professional and enthusiastic."}], "c2.sat_example_title": "Developing a scientific essay statement through the S.A.T loop", "c2.sat_example": {"phases": [{"label": "Self–AI", "steps": [{"actor": "self", "name": "Intent", "text": "A student wants to write their scientific essay about child maltreatment. They are interested in the role schools can play in preventing it and have a rough idea of what the statement could be: schools are important to prevent child maltreatment. However, they are unsure whether this is specific and arguable enough for the assignment."}, {"actor": "ai", "name": "Operationalize", "text": "The student asks AI in which ways they could be more specific regarding the statement. AI suggests exploring different types of schools, different forms of prevention, and different roles within schools where the responsibility to prevent child maltreatment should lie."}, {"actor": "self", "name": "Judge", "text": "The student considers the alternatives and decides that they will focus on primary schools and the role of teachers. Their statement is now: primary school teachers are important to prevent child maltreatment."}, {"actor": "ai", "name": "Refine", "text": "The student asks AI to help refine the wording of their statement without changing its underlying position. AI suggests changing \"are important\" for \"should play a larger role\". The student now has a specific and arguable statement: primary school teachers should play a larger role in preventing child maltreatment."}]}, {"label": "Self–Team", "steps": [{"actor": "self", "name": "Present", "text": "In class, the student shares their statement with their classmates and asks for their feedback."}, {"actor": "team", "name": "Feedback", "text": "Overall, the student''s classmates understand the statement and think it''s a good dilemma. One classmate asks whether prevention refers to primary prevention, aimed at all students, or secondary prevention, aimed at children who have risk factors for maltreatment."}, {"actor": "self", "name": "Integrate", "text": "The student realizes that the statement is still too general. They reflect on the question raised by their classmate and agree that they should be more specific regarding that element."}, {"actor": "team", "name": "Expand", "text": "The student and their classmates discuss whether primary or secondary prevention fits the statement better. During the discussion, another classmate asks what kind of preventive measures they are thinking about."}]}, {"label": "Self–AI", "steps": [{"actor": "self", "name": "Intent", "text": "The student wants to make the statement more specific regarding the type of prevention and the preventive measures teachers could use. However, they realize they lack knowledge about these concepts."}, {"actor": "ai", "name": "Operationalize", "text": "The student asks AI to clarify the concepts and provide some examples."}, {"actor": "self", "name": "Judge", "text": "The student evaluates the explanations and the examples and decides that education about recognizing inappropriate behavior and seeking help fits their intended focus best. They also decide that they want the intervention to be delivered as part of regular classroom education to all students."}, {"actor": "ai", "name": "Refine", "text": "The student asks AI to help formulate a statement that is more specific, including the new insights. AI suggests several formulations, and the student selects the one that best reflects their intended position: primary school teachers should play a larger role in the prevention of child maltreatment by providing all students with education on recognizing inappropriate behavior and seeking help."}]}], "note": "The example ends here, but the S.A.T process does not have to stop here. If the student feels that the idea still needs to be developed or wants to ask for feedback, they can start another Self–Team or Self–AI cycle."}}'::jsonb),
('ped','c3','{"c3.techniques.clear_instruction": {"bad": "\"Summarize this paper\"", "good": "\"Summarize this paper''s main argument and research methodology in two sentences each. This is for an undergraduate pedagogical sciences class presentation.\""}, "c3.techniques.role": {"bad": "\"Check my Boolean search string\"", "good": "\"You are a search strategy advisor for academic databases. Review the Boolean search string I wrote. If there are logical errors, don''t fix them directly — ask me questions about what went wrong.\""}, "c3.techniques.task_decomposition": {"bad": "\"Build my scientific essay outline\"", "good": "Step 1: \"Extract the main argument from each of these three articles\" → Step 2: \"Compare the main arguments and identify similarities and differences between the articles\" → Step 3: \"Suggest possible ways to organize these articles based on their main arguments\""}, "c3.techniques.few_shot": {"good": "\"Summarize each paper''s core claim in one sentence, like this:\nSmith (2022): Supportive teacher-student relationships can reduce the negative impact of family-related risk factors on children''s socio-emotional development.\nDo the same for the remaining three papers.\""}, "c3.techniques.chain_of_thought": {"bad": "\"Are the conclusions of these two papers contradictory?\"", "good": "\"Determine whether the conclusions of these two papers contradict each other. First, summarize each paper''s core claim. Then compare where they overlap and where they differ. Finally, explain step by step whether the difference is a genuine contradiction or a difference in scope or conditions.\""}, "c3.techniques.output_format": {"bad": "\"Compare these three papers\"", "good": "\"Create a comparison table for these three papers. Columns: author/year, research question, methodology, key findings, limitations. One sentence per cell.\""}, "c3.critique.read": "Student asked \"Extract the main argument from each of these three articles.\" AI returned three paragraphs. Observation: AI identified one main argument for each article and wrote in paragraph form.", "c3.critique.question": "Are these really the main arguments of the articles, or did AI generalize? Did AI accurately distinguish the authors'' main arguments from secondary points? Article B''s argument sounds stronger than I remember — is that what the authors actually concluded? I only asked for the main argument, but AI added \"practical implications\" — did it exceed my request scope?", "c3.critique.verify": "Checking Article A: AI correctly identified the main argument, but also added a secondary argument. Checking Article B: AI generalized the original claim. Checking Article C: AI provided \"practical implications\" based on the findings, rather than the main argument. The \"practical implications\" section covers a stage I haven''t reached yet.", "c3.critique.decide": "Article A''s main argument is usable as a starting point. Article B''s main argument needs adjustment. Article C''s practical implications are deleted — may re-prompt after checking the original.", "c3.amd_example": {"title": "Worked example — Main argument extraction", "intro": "Student asked AI to extract the main argument from each of the three articles. AI presented three main arguments:", "items": [{"text": "Article A: \"Supportive teacher-student relationships are associated with better socio-emotional development in children\"", "tag": "adopt", "reason": "Matches the original article''s main argument. Usable as a starting point for organizing the evidence for and against my statement."}, {"text": "Article B: \"Parental involvement in schools leads to better educational outcomes\"", "tag": "modify", "reason": "Direction is correct, but AI generalized a \"positive association\" into a \"causal relationship.\" Corrected to \"positive association.\" Original article re-checked."}, {"text": "Article C: \"Schools should implement mandatory parent-training programmes\"", "tag": "discard", "reason": "I asked for the article''s main argument, not practical implications. This recommendation does not represent the article''s central claim. Deleted. Record: \"AI exceeded request scope by adding practical implications.\""}]}, "c3.template_compare.md": [{"heading": "Role", "lines": ["You are an academic writing assistant."]}, {"heading": "Task", "lines": ["Extract the main argument from each of", "these three articles."]}, {"heading": "Context", "lines": ["I am writing a scientific essay for", "\"Inleiding in opvoeding en onderwijs\"."]}, {"heading": "Constraints", "lines": ["- Do not summarize each paper individually", "- Base your response only on the evidence", "  presented in each article", "- Do not add interpretations or practical", "  implications"]}, {"heading": "Output Format", "lines": ["Numbered list, one article per item.", "For each article, state its main argument", "in one or two sentences."]}], "c3.template_compare.xml": [{"tag": "role", "lines": ["You are an academic writing assistant."]}, {"tag": "task", "lines": ["Extract the main argument from each of", "these three articles."]}, {"tag": "context", "lines": ["I am writing a scientific essay for", "\"Inleiding in opvoeding en onderwijs\"."]}, {"tag": "constraints", "lines": ["Do not summarize each paper individually.", "Base your response only on the evidence", "presented in each article.", "Do not add interpretations or practical", "implications."]}, {"tag": "output_format", "lines": ["Numbered list, one article per item.", "For each article, state its main argument", "in one or two sentences."]}], "c3.full_example_title": "Full worked example — Connecting articles to a statement", "c3.full_example": [{"tag": "role", "lines": ["You are an academic writing assistant for a", "first-year pedagogical sciences student."]}, {"tag": "task", "lines": ["Extract the main argument from each of the", "following three journal articles. Focus on the", "authors'' central claim, not on secondary points", "or practical implications."]}, {"tag": "context", "lines": ["I am writing a scientific essay for my course", "\"Inleiding in opvoeding en onderwijs\". I have", "read all three papers. I am currently at the", "stage of organizing my sources before drafting", "an outline."]}, {"tag": "constraints", "lines": ["Do not summarize each paper individually.", "Base your response only on the evidence", "presented in each article.", "Do not add interpretations or practical", "implications."]}, {"tag": "steps", "lines": ["1. Read the three abstracts I provide below.", "2. Identify the authors'' main argument in each", "   article.", "3. State each main argument clearly and concisely."]}, {"tag": "examples", "lines": ["Example argument format:", "\"Article A: Supportive teacher-student", "relationships are associated with better", "socio-emotional development in children\""]}, {"tag": "output_format", "lines": ["Numbered list, one article per item.", "For each article, state its main argument", "in one or two sentences."]}]}'::jsonb);

create table public.workspace_submissions (
 id uuid primary key default gen_random_uuid(),
 client_id uuid not null,
 course text not null, chapter text not null,
 author_id uuid not null references auth.users(id), author_name text not null,
 summary text not null check (length(btrim(summary)) between 1 and 12000),
 slots jsonb not null, base_slots jsonb not null,
 base_release uuid, saved_at timestamptz not null,
 submitted_at timestamptz not null default now(),
 status text not null default 'pending' check(status in ('pending','approved','revision','rejected')),
 revision integer not null default 1,
 reviewer_id uuid references auth.users(id), reviewer_name text,
 decision_reason text, decided_at timestamptz,
 unique(author_id,client_id),
 foreign key(course,chapter) references public.workspace_content_sources(course,chapter)
);
create index workspace_submissions_queue on public.workspace_submissions(submitted_at desc);
create table public.workspace_beta_content (
 course text not null, chapter text not null,
 submission_id uuid not null references public.workspace_submissions(id),
 slots jsonb not null, approved_at timestamptz not null default now(),
 primary key(course,chapter),
 foreign key(course,chapter) references public.workspace_content_sources(course,chapter)
);
-- Only the approved content is public, matching the existing public Beta pages.
-- Drafts, author identity, review comments and pending submissions are never public.
alter table public.workspace_content_sources enable row level security;
alter table public.workspace_submissions enable row level security;
alter table public.workspace_beta_content enable row level security;
revoke all on public.workspace_content_sources,public.workspace_submissions,public.workspace_beta_content from public,anon,authenticated;
grant select on public.workspace_submissions to authenticated;
grant select on public.workspace_beta_content to anon,authenticated;
grant all on public.workspace_content_sources,public.workspace_submissions,public.workspace_beta_content to service_role;
create policy team_reads_submissions on public.workspace_submissions for select to authenticated
 using ((select public.workspace_role()) is not null);
create policy beta_reads_approved on public.workspace_beta_content for select to anon,authenticated using (true);

-- The supported slot schema is fixed by the source or most recent approved copy.
create or replace function public.workspace_valid_content(value jsonb, baseline jsonb, field text default '') returns boolean
language plpgsql immutable set search_path = '' as $$
declare k text; v jsonb; i integer;
begin
 if value is null or baseline is null or jsonb_typeof(value) <> jsonb_typeof(baseline) then return false; end if;
 if jsonb_typeof(baseline) = 'string' then
  if length(value #>> '{}') > 100000 then return false; end if;
  if field = 'actor' and baseline #>> '{}' in ('student','ai') then return value #>> '{}' in ('student','ai'); end if;
  if field = 'tag' and baseline #>> '{}' in ('adopt','modify','discard') then return value #>> '{}' in ('adopt','modify','discard'); end if;
  return true;
 elsif jsonb_typeof(baseline) = 'array' then
  if jsonb_array_length(value) <> jsonb_array_length(baseline) then return false; end if;
  for i in 0..jsonb_array_length(baseline)-1 loop
   if not public.workspace_valid_content(value->i,baseline->i) then return false; end if;
  end loop;
  return true;
 elsif jsonb_typeof(baseline) = 'object' then
  for k,v in select * from jsonb_each(baseline) loop
   if not public.workspace_valid_content(value->k,v,k) then return false; end if;
  end loop;
  for k in select jsonb_object_keys(value) loop
   if not baseline ? k and not (k = 'typing_note' and baseline ? 'typing' and jsonb_typeof(value->k) = 'string' and length(value->>k) <= 100000) then return false; end if;
  end loop;
  return true;
 end if;
 return value = baseline;
end;
$$;
revoke all on function public.workspace_valid_content(jsonb,jsonb,text) from public,anon,authenticated;

create or replace function public.workspace_submit_content(
 p_client_id uuid,p_course text,p_chapter text,p_slots jsonb,p_base_slots jsonb,
 p_base_release uuid,p_saved_at timestamptz,p_summary text
) returns uuid language plpgsql security definer set search_path = '' as $$
declare uid uuid := auth.uid(); existing public.workspace_submissions; baseline jsonb; current_release uuid; result uuid; author text;
begin
 if public.workspace_role() is null then raise exception 'Active team membership is required.' using errcode='42501'; end if;
 if p_client_id is null then raise exception 'A submission ID is required.'; end if;
 -- Serialize retries per account and client ID before the idempotency lookup.
 perform pg_advisory_xact_lock(hashtextextended(uid::text || p_client_id::text,0));
 select * into existing from public.workspace_submissions where author_id=uid and client_id=p_client_id;
 if found then
  if existing.course is distinct from p_course or existing.chapter is distinct from p_chapter or existing.slots is distinct from p_slots then raise exception 'Submission ID already belongs to another content copy.'; end if;
  return existing.id;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('aiwise-beta:' || p_course || ':' || p_chapter,0));
 select slots into baseline from public.workspace_content_sources where course=p_course and chapter=p_chapter;
 if baseline is null then raise exception 'Unsupported course or chapter.'; end if;
 select submission_id,slots into current_release,baseline from public.workspace_beta_content where course=p_course and chapter=p_chapter;
 if not found then select slots into baseline from public.workspace_content_sources where course=p_course and chapter=p_chapter; end if;
 if current_release is distinct from p_base_release or baseline is distinct from p_base_slots then raise exception 'Beta has changed. Reload Studio and reapply your edits before submitting.'; end if;
 if p_slots is null or octet_length(p_slots::text)>2000000 or not public.workspace_valid_content(p_slots,baseline) then raise exception 'The submitted content does not match the supported slot structure.'; end if;
 if p_saved_at is null or p_summary is null or length(btrim(p_summary)) not between 1 and 12000 then raise exception 'A saved draft and change summary are required.'; end if;
 select coalesce(nullif(left(btrim(raw_user_meta_data->>'display_name'),80),''),'Team member') into author from auth.users where id=uid;
 insert into public.workspace_submissions(client_id,course,chapter,author_id,author_name,summary,slots,base_slots,base_release,saved_at)
 values(p_client_id,p_course,p_chapter,uid,author,btrim(p_summary),p_slots,p_base_slots,p_base_release,p_saved_at) returning id into result;
 return result;
end;
$$;

create or replace function public.workspace_decide_content(p_id uuid,p_revision integer,p_status text,p_reason text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare r public.workspace_submissions; current_release uuid; reviewer text;
begin
 if public.workspace_role() is distinct from 'admin' then raise exception 'Administrator permission is required.' using errcode='42501'; end if;
 if p_status is null or p_status not in ('approved','revision','rejected') or p_reason is null or length(btrim(p_reason)) not between 1 and 12000 then raise exception 'Choose a decision and enter a reason.'; end if;
 select * into r from public.workspace_submissions where id=p_id for update;
 if not found or r.status <> 'pending' or r.revision is distinct from p_revision then raise exception 'This request already changed. Refresh before reviewing.'; end if;
 if p_status='approved' then
  perform pg_advisory_xact_lock(hashtextextended('aiwise-beta:' || r.course || ':' || r.chapter,0));
  select submission_id into current_release from public.workspace_beta_content where course=r.course and chapter=r.chapter;
  if current_release is distinct from r.base_release then raise exception 'A newer version is already in Beta. Request revision instead of overwriting it.'; end if;
  insert into public.workspace_beta_content(course,chapter,submission_id,slots) values(r.course,r.chapter,r.id,r.slots)
   on conflict(course,chapter) do update set submission_id=excluded.submission_id,slots=excluded.slots,approved_at=now();
 end if;
 select coalesce(nullif(left(btrim(raw_user_meta_data->>'display_name'),80),''),'Administrator') into reviewer from auth.users where id=auth.uid();
 update public.workspace_submissions set status=p_status,revision=revision+1,reviewer_id=auth.uid(),reviewer_name=reviewer,decision_reason=btrim(p_reason),decided_at=now() where id=p_id;
 return p_id;
end;
$$;
revoke all on function public.workspace_submit_content(uuid,text,text,jsonb,jsonb,uuid,timestamptz,text),public.workspace_decide_content(uuid,integer,text,text) from public,anon;
grant execute on function public.workspace_submit_content(uuid,text,text,jsonb,jsonb,uuid,timestamptz,text),public.workspace_decide_content(uuid,integer,text,text) to authenticated;
comment on table public.workspace_submissions is 'Immutable submitted content. Direct browser writes are denied; guarded RPCs derive identity and enforce membership/admin decisions.';
notify pgrst, 'reload schema';
commit;
-- Bootstrap the first administrator explicitly in Table Editor: workspace_members.role = admin.
-- No account is automatically promoted. Existing members remain members.
